import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Estimates — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Estimates — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/estimates"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Estimates — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/estimates"}]]},"headers":[],"relativePath":"user-guide/estimates.md","filePath":"user-guide/estimates.md","lastUpdated":1785970856000}'),n={name:"user-guide/estimates.md"};function r(i,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="estimates-—-user-guide" tabindex="-1">Estimates — User Guide <a class="header-anchor" href="#estimates-—-user-guide" aria-label="Permalink to &quot;Estimates — User Guide&quot;">​</a></h1><h2 id="who-can-use-estimates" tabindex="-1">Who can use Estimates <a class="header-anchor" href="#who-can-use-estimates" aria-label="Permalink to &quot;Who can use Estimates&quot;">​</a></h2><p>Your workspace must have <strong>Invoices</strong> installed first, then the <strong>Estimates</strong> module (both free from Marketplace). Marketplace blocks installing Estimates until Invoices is entitled. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>accept</code>, <code>convert</code> as needed).</p><p>Without <strong>assign</strong>, you only see estimates assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Estimates</strong> from the sidebar (<strong>Billing</strong>, after Credit Notes). Search by title or number, filter by status or assignee, toggle <strong>My estimates</strong>, and switch KPI cards (Total, Mine, Draft, Sent, Accepted, Accepted value) to quick-filter the table. The table shows the <strong>latest note</strong> and a <strong>Converted</strong> badge once an estimate has produced an invoice.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted estimate from the row menu</li><li><strong>Delete permanently</strong> requires <code>estimates.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-an-estimate" tabindex="-1">Create an estimate <a class="header-anchor" href="#create-an-estimate" aria-label="Permalink to &quot;Create an estimate&quot;">​</a></h2><ol><li>Click <strong>New estimate</strong></li><li>Enter a title, currency (defaults to your workspace currency; full shared currency list), valid-until date, and notes</li><li>Optionally link a <strong>Contact</strong> or <strong>Company</strong> (when Contacts/Companies is installed)</li><li>Optionally link an <strong>Opportunity</strong>, and a <strong>Quotation</strong> for that opportunity, for traceability back to the sales pipeline</li><li>Add line items (description, quantity, unit price, tax rate) — subtotal, tax, and total are calculated automatically</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the detail sheet while the estimate is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>An estimate starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → sent</code>) — marks the estimate as sent to the customer (does not email the customer or attach a PDF yet)</li><li><strong>Accept</strong> (<code>sent → accepted</code>) or <strong>Reject</strong> / <strong>Expire</strong> via the status action</li></ul><p>Invalid transitions (e.g. accepting directly from Draft) are rejected with a validation error.</p><h2 id="convert-to-invoice" tabindex="-1">Convert to invoice <a class="header-anchor" href="#convert-to-invoice" aria-label="Permalink to &quot;Convert to invoice&quot;">​</a></h2><p>Once an estimate is <strong>Sent</strong> or <strong>Accepted</strong>, use <strong>Convert to invoice</strong> from the detail sheet or row menu:</p><ul><li>Creates a new <strong>draft</strong> invoice with the same title, notes, currency, contact/company, quotation link, assignee, and a copy of every line item</li><li>Marks the estimate <strong>Accepted</strong> automatically if it wasn&#39;t already</li><li>The estimate detail sheet then shows a link to the <strong>converted invoice</strong></li><li>An estimate can only be converted <strong>once</strong> — the action is hidden once a converted invoice already exists</li></ul><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail sheet or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the estimate</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, conversion, note, and delete/restore events</li></ul><h2 id="related-records" tabindex="-1">Related records <a class="header-anchor" href="#related-records" aria-label="Permalink to &quot;Related records&quot;">​</a></h2><p>Every estimate detail sheet shows its linked <strong>Contact</strong>, <strong>Company</strong>, <strong>Opportunity</strong>, <strong>Quotation</strong>, and — once converted — the resulting <strong>Invoice</strong>, each with a link to jump straight to that record&#39;s detail view.</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Estimate PDFs/e-mail delivery, reversing a conversion, and standalone estimates that don&#39;t require Invoices are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',25)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
